begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.begin_student_preview(uuid)','execute'),'anonymous preview entry denied');
select ok(not has_function_privilege('authenticated','public.current_auth_session()','execute'),'session extraction internal');
select ok(not has_schema_privilege('authenticated','private','usage'),'preview records private');
insert into auth.users(id,email_confirmed_at) values('a4000000-0000-0000-0000-000000000001',now()),('a4000000-0000-0000-0000-000000000002',now()),('a4000000-0000-0000-0000-000000000003',now()),('a4000000-0000-0000-0000-000000000004',null);
insert into public.users(id,role) values('a4000000-0000-0000-0000-000000000001','PARENT'),('a4000000-0000-0000-0000-000000000002','PARENT'),('a4000000-0000-0000-0000-000000000003','STUDENT'),('a4000000-0000-0000-0000-000000000004','PARENT');
insert into public.parent_profiles(user_id,display_name) values('a4000000-0000-0000-0000-000000000001','Parent A'),('a4000000-0000-0000-0000-000000000002','Parent B'),('a4000000-0000-0000-0000-000000000004','Unverified');
insert into public.student_profiles(id,user_id,display_name) values('a4100000-0000-0000-0000-000000000001','a4000000-0000-0000-0000-000000000003','Selected'),('a4100000-0000-0000-0000-000000000002',null,'Sibling'),('a4100000-0000-0000-0000-000000000003',null,'Other family');
insert into public.parent_student_relationships values('a4000000-0000-0000-0000-000000000001','a4100000-0000-0000-0000-000000000001'),('a4000000-0000-0000-0000-000000000001','a4100000-0000-0000-0000-000000000002'),('a4000000-0000-0000-0000-000000000002','a4100000-0000-0000-0000-000000000003');
insert into auth.sessions(id,user_id) values('a4200000-0000-0000-0000-000000000001','a4000000-0000-0000-0000-000000000001'),('a4200000-0000-0000-0000-000000000002','a4000000-0000-0000-0000-000000000001'),('a4200000-0000-0000-0000-000000000003','a4000000-0000-0000-0000-000000000003'),('a4200000-0000-0000-0000-000000000004','a4000000-0000-0000-0000-000000000004');
insert into public.student_skills(student_id,skill_id) select id,'00000000-0000-0000-0000-000000000011' from public.student_profiles where id::text like 'a410%';
insert into public.student_courses(student_id,course_id) values('a4100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002');
insert into public.homework_assignments(student_id) select id from public.student_profiles where id::text like 'a410%';
insert into public.lesson_schedules(student_id,starts_at) select id,now()+interval '7 days' from public.student_profiles where id::text like 'a410%';
insert into public.parent_reports(student_id,report) values('a4100000-0000-0000-0000-000000000001','{}');
insert into public.consents(parent_id,student_id,consent_type,granted,policy_version,source) values('a4000000-0000-0000-0000-000000000001','a4100000-0000-0000-0000-000000000001','microphone',false,'draft-v1','parent_portal');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000001","session_id":"a4200000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(public.active_preview_student(),null::uuid,'starts in parent mode');
select is((select count(*)::integer from public.student_profiles where id::text like 'a410%'),2,'parent sees two authorized students');
select throws_ok($$select public.begin_student_preview('a4100000-0000-0000-0000-000000000003')$$,'42501',null,'another family cannot be previewed');
select is(public.begin_student_preview('a4100000-0000-0000-0000-000000000001'),'a4100000-0000-0000-0000-000000000001'::uuid,'preview authorized student');
select is(public.active_preview_student(),'a4100000-0000-0000-0000-000000000001'::uuid,'canonical session scope persists');
select is((select count(*)::integer from public.student_profiles where id::text like 'a410%'),1,'sibling profiles hidden');
select is((select count(*)::integer from public.parent_student_relationships),1,'sibling relationship hidden');
select is((select count(*)::integer from public.parent_profiles),0,'parent account hidden');
select is((select count(*)::integer from public.users),0,'parent identity hidden');
select is((select count(*)::integer from public.consents),0,'real consent record hidden in preview');
select is((select count(*)::integer from public.parent_reports),0,'real parent report hidden in preview');
select is((select count(*)::integer from public.homework_assignments),1,'homework selected student only');
select is((select count(*)::integer from public.lesson_schedules),1,'same canonical schedule scoped');
select is((select count(*)::integer from public.student_skills),1,'skill state selected student only');
select is((select count(*)::integer from public.curriculum_versions where id='00000000-0000-0000-0000-000000000101'),1,'exact enrolled publication readable while parent identity stays hidden');
select is((select count(*)::integer from public.questions),0,'private answers remain hidden');
select throws_ok($$select public.create_parent_student(gen_random_uuid(),'Forbidden',8,null)$$,'42501',null,'cannot create sibling during preview');
select throws_ok($$select public.update_parent_student('a4100000-0000-0000-0000-000000000001','Forbidden',8,null)$$,'42501',null,'preview cannot mutate selected profile');
select throws_ok($$select public.record_parent_consent(gen_random_uuid(),'a4100000-0000-0000-0000-000000000001','microphone','draft-v1',false)$$,'42501',null,'preview cannot manage consent');
select throws_ok($$select public.enroll_parent_student(gen_random_uuid(),'a4100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101','{}')$$,'42501',null,'preview cannot enroll even selected student');
select throws_ok($$select public.begin_student_preview('a4100000-0000-0000-0000-000000000002')$$,'42501',null,'switching requires explicit parent return');
select throws_ok($$update public.student_skills set mastery_score=1$$,'42501',null,'direct privileged writes denied');
select throws_ok($$select * from private.parent_student_previews$$,'42501',null,'cannot alter or inspect preview session records');
-- A second session for the same parent is not promoted/restricted by session one.
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000001","session_id":"a4200000-0000-0000-0000-000000000002"}',true);
select is(public.active_preview_student(),null::uuid,'other parent session unaffected');
select is((select count(*)::integer from public.student_profiles where id::text like 'a410%'),2,'second parent session retains authorized context');
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000001","session_id":"a4200000-0000-0000-0000-000000000001"}',true);
select is(public.end_student_preview(),'a4100000-0000-0000-0000-000000000001'::uuid,'explicit return restores parent');
select is(public.active_preview_student(),null::uuid,'preview scope cleared');
select is(public.end_student_preview(),null::uuid,'repeat exit no duplicate audit');
select is((select count(*)::integer from public.student_profiles where id::text like 'a410%'),2,'student switching restored');
reset role;
select is((select count(*)::integer from public.audit_logs where actor_id='a4000000-0000-0000-0000-000000000001' and action='preview.started'),1,'preview entry audited once');
select is((select count(*)::integer from public.audit_logs where actor_id='a4000000-0000-0000-0000-000000000001' and action='preview.ended'),1,'explicit exit audited once');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000003","session_id":"a4200000-0000-0000-0000-000000000003"}',true);
select throws_ok($$select public.begin_student_preview('a4100000-0000-0000-0000-000000000001')$$,'42501',null,'student cannot impersonate parent');
select throws_ok($$select public.end_student_preview()$$,'42501',null,'student cannot restore parent access');
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000004","session_id":"a4200000-0000-0000-0000-000000000004"}',true);
select throws_ok($$select public.begin_student_preview('a4100000-0000-0000-0000-000000000001')$$,'42501',null,'unverified parent denied');
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000001","session_id":"a4200000-0000-0000-0000-000000000003"}',true);
select throws_ok($$select public.begin_student_preview('a4100000-0000-0000-0000-000000000001')$$,'42501',null,'session must belong to actor');
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select public.begin_student_preview('a4100000-0000-0000-0000-000000000001')$$,'42501',null,'sessionless identity cannot enter preview');
-- Revocation does not silently restore parent mode or authorize the learner.
select set_config('request.jwt.claims','{"sub":"a4000000-0000-0000-0000-000000000001","session_id":"a4200000-0000-0000-0000-000000000001"}',true);
select public.begin_student_preview('a4100000-0000-0000-0000-000000000001');
reset role;
delete from public.consents where parent_id='a4000000-0000-0000-0000-000000000001';
delete from public.parent_student_relationships where parent_id='a4000000-0000-0000-0000-000000000001' and student_id='a4100000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::integer from public.student_profiles where id::text like 'a410%'),0,'revoked relationship denies preview and sibling access');
select is(public.active_preview_student(),'a4100000-0000-0000-0000-000000000001'::uuid,'revocation does not restore parent mode');
select * from finish();
rollback;
